def transform(grid):
    h=len(grid)//4
    offsets={5:0,4:1,2:2,8:3}
    out=[]
    for r in range(h):
        row=[]
        for c in range(len(grid[0])):
            value=0
            for color in (2,8,4,5):
                if grid[offsets[color]*h+r][c] == color:
                    value=color
            row.append(value)
        out.append(row)
    return out
